parameters.jsCode:
let sql =
  $json.output?.sql ||
  $json.sql ||
  '';

sql = sql
  .replace(/```sql/gi, '')
  .replace(/```/g, '')
  .trim();

const forbidden =
  /\b(INSERT|UPDATE|DELETE|DROP|ALTER|TRUNCATE|CREATE|GRANT|REVOKE|COPY|CALL|EXECUTE|MERGE|VACUUM)\b/i;

const allowedStart =
  /^(SELECT|WITH)\b/i.test(sql);

const statements =
  sql
    .split(';')
    .filter(s => s.trim().length > 0);

if (!allowedStart) {
  throw new Error(
    'SQL rejected: query must begin with SELECT or WITH.'
  );
}

if (forbidden.test(sql)) {
  throw new Error(
    'SQL rejected: destructive SQL detected.'
  );
}

if (statements.length > 1) {
  throw new Error(
    'SQL rejected: multiple SQL statements are not allowed.'
  );
}

sql = sql.replace(/;+\s*$/, '');

return [
  {
    json: {
      question:
        $('Prepare SQL Context').first().json.question,

      safe_sql: sql,

      explanation:
        $json.output?.explanation ||
        $json.explanation ||
        '',

      expected_columns:
        $json.output?.expected_columns ||
        $json.expected_columns ||
        [],

      security_check: 'PASSED'
    }
  }
];

